package gateway
import("context";"encoding/json";"errors";"net/http/httptest";"strings";"testing";"github.com/madkoding/kitties/internal/chat";"github.com/madkoding/kitties/internal/kitty")
type metadataGatewayChats struct{*lexopenStagedChats;calls int;last chat.StagedMetadataAction;err error}
func(c *metadataGatewayChats)StageMetadataAction(_ context.Context,id string,b chat.StagedMetadataAction)(chat.StagedMetadataActionResult,error){c.calls++;c.last=b;if c.err!=nil{return chat.StagedMetadataActionResult{},c.err};return chat.StagedMetadataActionResult{State:"pending",ApprovalID:"exact-metadata-approval",RequestID:b.RequestID},nil}
func metadataGatewayFixture()(*Server,*metadataGatewayChats){_,old:=stagedGatewayFixture();c:=&metadataGatewayChats{lexopenStagedChats:old};return New(&fakeFleet{kitties:map[string]*kitty.Kitty{}},c,"fixture-token","fixture"),c}
func metadataGatewayBody()map[string]any{return map[string]any{"request_id":"exact-request","kitty":"owned","connector":"altazor-dropbox-0123456789abcdef","action":"search","args":map[string]any{"query":".pdf","limit":"5"},"text":"Muestra nombres PDF."}}
func TestLexOpenStagedMetadataGatewayBoundaryCapabilityAndExactBody(t *testing.T){s,c:=metadataGatewayFixture();rec:=httptest.NewRecorder();s.ServeHTTP(rec,httptest.NewRequest("GET","/v1/health",nil));var health map[string]any;json.Unmarshal(rec.Body.Bytes(),&health);if health["lexopen_staged_metadata_actions"]!="v1"||health["lexopen_staged_file_actions"]!="v1"{t.Fatal("capability missing")};r:=lexopenOAuthRequest(s,"/v1/lexopen/chats/exact-chat/metadata-actions",metadataGatewayBody(),"127.0.0.1:4321","fixture-token");var receipt map[string]any;json.Unmarshal(r.Body.Bytes(),&receipt);if r.Code!=200||len(receipt)!=3||receipt["state"]!="pending"||c.calls!=1||c.last.Args["query"]!=".pdf"||c.last.Args["limit"]!="5"||r.Header().Get("Cache-Control")!="no-store"{t.Fatal("wrong pending/exact request")};for _,tc:=range []struct{remote,token string;body any;status int}{{"192.0.2.1:1234","fixture-token",metadataGatewayBody(),403},{"127.0.0.1:1234","",metadataGatewayBody(),401},{"127.0.0.1:1234","fixture-token",`{"unknown":"field"}`,400},{"127.0.0.1:1234","fixture-token",`{} {}`,400},{"127.0.0.1:1234","fixture-token",strings.Repeat("x",33000),400}}{s,c:=metadataGatewayFixture();r:=lexopenOAuthRequest(s,"/v1/lexopen/chats/exact-chat/metadata-actions",tc.body,tc.remote,tc.token);if r.Code!=tc.status||c.calls!=0{t.Fatal("bad request reached staging")}};legacy,_:=stagedGatewayFixture();r=lexopenOAuthRequest(legacy,"/v1/lexopen/chats/exact-chat/metadata-actions",metadataGatewayBody(),"127.0.0.1:1234","fixture-token");if r.Code!=503{t.Fatal("unsupported server inferred fallback")}}
func TestLexOpenStagedMetadataGatewaySafeFailure(t *testing.T){s,c:=metadataGatewayFixture();c.err=errors.New("private-provider-detail");r:=lexopenOAuthRequest(s,"/v1/lexopen/chats/exact-chat/metadata-actions",metadataGatewayBody(),"127.0.0.1:1234","fixture-token");if r.Code!=503||strings.Contains(r.Body.String(),"private-provider-detail"){t.Fatal("unsafe stage failure")}}
